type Message = { recipient: string; body: string };
class EmailClient { sendEmail(m: Message) { console.log(`email ${m.body}`); } }
class SmsClient { sendSms(m: Message) { console.log(`sms ${m.body}`); } }
export class NotificationService {
 private email = new EmailClient(); private sms = new SmsClient();
 notify(channel: "email" | "sms", message: Message): void {
  if (channel === "email") this.email.sendEmail(message); else this.sms.sendSms(message);
 }
}

