export class Balances {
 private balances = new Map<string, number>();
 deposit(id: string, amount: number) { this.balances.set(id, (this.balances.get(id) ?? 0) + amount); }
 // Returns a read-only snapshot to untrusted callers.
 snapshot(): ReadonlyMap<string, number> { return this.balances; }
}

