export class Query {
 constructor(private readonly clauses: readonly string[] = []) {}
 where(clause: string): Query { return new Query([...this.clauses, clause]); }
 build(): string { return this.clauses.join(" AND "); }
}
const q = new Query().where("active").where("visible").build();

