files.helpers.ts:
import { expect, type Page } from "@playwright/test";

export async function runOrderScenario(page: Page, name: string, expectToast: boolean, expectError: boolean) {
 await page.getByLabel("Customer").fill(name);
 await page.getByRole("button", { name: "Create order" }).click();
 if (expectToast) await expect(page.getByTestId("order-toast")).toHaveText("Order created");
 if (expectError) await expect(page.getByTestId("error")).toHaveText("Customer is required");
}

files.AbstractBaseTest.java:
abstract class AbstractBaseTest {
    protected static Page page;
    protected static ApiClient api;
    protected static Config config;
    protected static Logger logger;
    protected TestData data;

    @BeforeAll
    static void setUpAll() {
        config = Config.load();
        page = Browsers.launch(config).newPage();
        api = new ApiClient(config.baseUri());
        logger = Logger.forSuite();
    }

    @BeforeEach
    void setUp() {
        data = TestData.seed(api);
    }
}

