import { type Page } from "@playwright/test";

export class LoginPage {
  static current: Page;
  static lastUser = "";

  static async login(user: string): Promise<void> {
    LoginPage.lastUser = user;
    await LoginPage.current.getByLabel("User").fill(user);
    await LoginPage.current.getByRole("button", { name: "Sign in" }).click();
  }
}

